/* ============ Classifications & Labels reference ============
   Per country: framework, quality pyramid (top→bottom), classification/aging systems,
   label-term glossary, and exam traps. Intensive study reference. */
var INTRO_CLASS=[
{name:"France",flag:"🇫🇷",
 framework:"EU origin tiers: AOC/AOP (strictest) › IGP (Vin de Pays) › Vin de France. Quality is tied to PLACE; the grape is usually implied by the appellation, not printed — and the word 'Cru' means something different in every region.",
 pyramid:[
  {t:"AOC / AOP",d:"Appellation d'Origine Contrôlée/Protégée — defined area, permitted grapes, max yields, methods. The strictest, top tier."},
  {t:"IGP (Vin de Pays)",d:"Indication Géographique Protégée — broader regions, looser rules; the grape variety is often named on the label."},
  {t:"Vin de France",d:"Basic tier, no geographic claim. Vintage and variety may still appear."}
 ],
 systems:[
  {n:"Bordeaux — 1855 Classification",d:"Médoc reds (plus Haut-Brion) ranked into FIVE growths, Premier → Cinquième Cru, on 1855 market prices. Essentially frozen; only change: Mouton Rothschild promoted to First Growth in 1973. Sauternes/Barsac ranked separately: Premier Cru Supérieur (d'Yquem) above Premiers and Deuxièmes Crus."},
  {n:"Bordeaux — St-Émilion",d:"Revised about every 10 years (so it can change!). Tiers: Premier Grand Cru Classé A, then B, then Grand Cru Classé, then plain 'Grand Cru' (the broad entry tier). TRAP: here 'Grand Cru' is near the bottom, not the top."},
  {n:"Bordeaux — Graves / Pessac-Léognan",d:"1959 classification: a single tier 'Cru Classé', awarded for red and/or white."},
  {n:"Bordeaux — Cru Bourgeois",d:"A separate Médoc system below the 1855 growths. Three tiers again (Cru Bourgeois, Supérieur, Exceptionnel), revised every 5 years."},
  {n:"Bordeaux — Pomerol",d:"Has NO official classification at all — Pétrus, Le Pin and the rest are unranked."},
  {n:"Burgundy",d:"Vineyard-based: Grand Cru (≈2%, the named vineyard only) › Premier Cru (village + '1er Cru' + vineyard) › Village (commune name) › Regional (Bourgogne). A Grand Cru label shows ONLY the vineyard name, e.g. 'Chambertin'."},
  {n:"Beaujolais — Crus",d:"10 named Crus (Morgon, Fleurie, Moulin-à-Vent…) › Beaujolais-Villages › Beaujolais. The Cru names do NOT say 'Beaujolais'."},
  {n:"Champagne — Échelle des Crus",d:"Grand Cru and Premier Cru rank whole VILLAGES (communes), not individual vineyards as in Burgundy."},
  {n:"Alsace — Grand Cru",d:"51 named single vineyards (lieux-dits). Otherwise Alsace labels by grape variety."}
 ],
 aging:[
  {t:"Champagne dosage (driest → sweetest, g/L)",d:"Brut Nature/Zéro (0–3) › Extra Brut (0–6) › Brut (0–12) › Extra Dry (12–17) › Sec (17–32) › Demi-Sec (32–50) › Doux (50+). TRAP: 'Extra Dry' is SWEETER than 'Brut'."},
  {t:"Alsace sweetness",d:"Vendange Tardive (late harvest) and the sweeter, rarer Sélection de Grains Nobles (botrytis)."}
 ],
 terms:[
  {t:"Cru",d:"'Growth' — a ranked vineyard/estate, but the meaning shifts by region (estate in Bordeaux, vineyard in Burgundy, village in Champagne)."},
  {t:"Château / Domaine",d:"Estate (Château is the Bordeaux term, Domaine the Burgundy term)."},
  {t:"Mis en bouteille au château/domaine",d:"Estate bottled."},
  {t:"Négociant",d:"A merchant who buys grapes, must or wine and bottles under their name."},
  {t:"Vieilles Vignes",d:"Old vines (unregulated term)."},
  {t:"Sur lie",d:"Aged on the lees (classic for Muscadet) — adds texture and a slight prickle."},
  {t:"Blanc de Blancs / Blanc de Noirs",d:"Sparkling from white grapes only / from black grapes only."},
  {t:"Supérieur",d:"Slightly higher minimum alcohol or aging — NOT a quality ranking."}
 ],
 traps:[
  "'Cru' is region-dependent: Bordeaux ranks ESTATES, Burgundy/Alsace rank VINEYARDS, Champagne ranks VILLAGES, and a Beaujolais 'Cru' is a named appellation.",
  "Grand Cru is the TOP in Burgundy/Alsace, but in St-Émilion plain 'Grand Cru' is a broad LOWER tier (below Grand Cru Classé and Premier Grand Cru Classé).",
  "Pomerol has no classification system.",
  "A Burgundy Grand Cru label shows only the vineyard name (no village).",
  "'Supérieur' means more alcohol/aging, not better quality."
 ]},

{name:"Italy",flag:"🇮🇹",
 framework:"EU tiers: DOCG (top) › DOC › IGT › Vino. DOCG and DOC together form 'DOP'. But tier ≠ quality — Super Tuscans are deliberately bottled as IGT. Watch for 'Classico', 'Riserva' and 'Superiore'.",
 pyramid:[
  {t:"DOCG",d:"Denominazione di Origine Controllata e Garantita — top; government-tasted, with a numbered seal across the capsule."},
  {t:"DOC",d:"Denominazione di Origine Controllata — controlled origin with set rules."},
  {t:"IGT",d:"Indicazione Geografica Tipica — broader; the home of the 'Super Tuscans'."},
  {t:"Vino (da Tavola)",d:"Basic table wine."}
 ],
 systems:[
  {n:"Classico",d:"The historic heartland of a zone (e.g. Chianti Classico, marked by the black rooster / gallo nero seal) — usually the higher-quality core."},
  {n:"Chianti Classico tiers",d:"Annata (standard) › Riserva (≥24 months aging) › Gran Selezione (top tier since 2014, ≥30 months, estate fruit)."},
  {n:"Barolo & Barbaresco",d:"Nebbiolo DOCGs. Single-vineyard crus are labeled as MGA (Menzioni Geografiche Aggiuntive). Barolo: ≥38 months (≥18 in wood); Riserva ≥62."},
  {n:"Brunello di Montalcino",d:"100% Sangiovese; long aging (≈5 years, Riserva 6) — among Italy's most prestigious DOCGs."},
  {n:"Super Tuscans",d:"Top Bordeaux-style or varietal wines bottled as IGT (e.g. Sassicaia, now its own Bolgheri DOC) to escape rigid DOC blend rules."}
 ],
 aging:[
  {t:"Riserva",d:"Extra aging beyond the normal wine — the minimum is defined per DOC/DOCG."},
  {t:"Superiore",d:"Higher minimum alcohol and often more aging."},
  {t:"Sweetness",d:"Secco (dry) · Abboccato (off-dry) · Amabile (medium-sweet) · Dolce (sweet)."}
 ],
 terms:[
  {t:"Annata",d:"Vintage; also the standard (non-Riserva) bottling."},
  {t:"Gran Selezione",d:"The top Chianti Classico tier (above Riserva)."},
  {t:"Vigna / MGA",d:"A single named vineyard."},
  {t:"Passito",d:"Wine from dried (appassimento) grapes — e.g. Amarone, Recioto."},
  {t:"Metodo Classico",d:"Traditional-method sparkling (e.g. Franciacorta)."},
  {t:"Spumante / Frizzante",d:"Fully sparkling / lightly sparkling."},
  {t:"Imbottigliato all'origine",d:"Estate bottled."},
  {t:"Azienda Agricola / Tenuta / Fattoria / Castello",d:"Types of wine estate."}
 ],
 traps:[
  "DOCG outranks DOC on paper, but a Super-Tuscan IGT can be pricier and finer than many DOCs — tier ≠ quality.",
  "Montepulciano is BOTH a place and a grape: Vino Nobile di Montepulciano = Sangiovese from a Tuscan town; Montepulciano d'Abruzzo = the grape grown in Abruzzo.",
  "The black rooster (Gallo Nero) seal = Chianti Classico.",
  "Gran Selezione is the TOP Chianti Classico tier, above Riserva."
 ]},

{name:"Spain",flag:"🇪🇸",
 framework:"Origin tiers run DOCa/DOQ (top) › DO › Vino de Calidad › Vino de la Tierra (IGP) › Vino, with Vino de Pago as a separate single-estate elite. But the terms that matter MOST on a Spanish label are the aging tiers — and unlike the US, they're legally defined.",
 pyramid:[
  {t:"DOCa / DOQ",d:"Denominación de Origen Calificada (Catalan: DOQ) — top tier, held by only Rioja (1991) and Priorat (2009)."},
  {t:"DO",d:"Denominación de Origen — the main quality-wine tier."},
  {t:"Vino de Calidad (VC)",d:"A stepping-stone tier below DO."},
  {t:"Vino de la Tierra",d:"IGP — regional country wine."},
  {t:"Vino",d:"Basic table wine."}
 ],
 systems:[
  {n:"Aging tiers (red — legally defined)",d:"Joven (young, little/no oak) › Crianza (≈2 yrs, ≥6–12 mo in oak) › Reserva (≈3 yrs, ≥1 yr in oak) › Gran Reserva (≈5 yrs, with long oak + bottle age). Whites/rosés have shorter minimums."},
  {n:"Vino de Pago (VP)",d:"A single prestigious estate granted its own appellation-level status — sits at the very top."},
  {n:"Rioja sub-zones & 2017 terms",d:"Rioja Alta, Rioja Alavesa, Rioja Oriental. Newer geographic claims: Vino de Zona › Vino de Municipio › Viñedo Singular (single-vineyard)."},
  {n:"Cava (method, not place)",d:"Traditional-method sparkling, mostly from Penedès. Reformed tiers: Cava de Guarda and Cava de Guarda Superior (Reserva, Gran Reserva, Paraje Calificado)."}
 ],
 aging:[
  {t:"Crianza",d:"Red ≈24 months total with significant oak — the everyday aged tier."},
  {t:"Reserva",d:"Red ≈36 months, with ≥1 year in oak."},
  {t:"Gran Reserva",d:"Red ≈60 months — long oak plus bottle age; made only in strong vintages."},
  {t:"Roble",d:"'Oak' — brief barrel contact, below Crianza."}
 ],
 terms:[
  {t:"Bodega",d:"Winery."},
  {t:"Cosecha / Vendimia",d:"Vintage / harvest."},
  {t:"Viña / Viñedo",d:"Vineyard."},
  {t:"Tinto / Blanco / Rosado",d:"Red / white / rosé."},
  {t:"Seco / Semi-seco / Dulce",d:"Dry / off-dry / sweet."},
  {t:"Embotellado en origen",d:"Estate bottled."}
 ],
 traps:[
  "Crianza / Reserva / Gran Reserva are LEGALLY DEFINED aging terms — the opposite of the unregulated US 'Reserve'.",
  "DOCa/DOQ is held by only TWO regions: Rioja and Priorat.",
  "Cava is a DO defined by method and producer, not a single town — most is made in Penedès, Catalonia.",
  "Gran Reserva = longest aging and only in top vintages (not just 'a big wine')."
 ]},

{name:"Portugal",flag:"🇵🇹",
 framework:"Still-wine tiers: DOC/DOP (top) › Vinho Regional (IGP) › Vinho. But Portugal's exam weight is in the STYLE classifications of Port and Madeira — especially the Ruby vs Tawny split and the Colheita/Vintage trap.",
 pyramid:[
  {t:"DOC / DOP",d:"Denominação de Origem Controlada/Protegida — top origin tier (e.g. Douro, Dão, Vinho Verde)."},
  {t:"Vinho Regional",d:"IGP — larger regions (e.g. Lisboa, Alentejano)."},
  {t:"Vinho",d:"Basic table wine."}
 ],
 systems:[
  {n:"Port — Ruby family (fresh, fruity)",d:"Ruby › Reserve › LBV (Late Bottled Vintage) › Crusted › Vintage. Vintage Port is declared only in great years, ages in bottle, and throws a sediment."},
  {n:"Port — Tawny family (oxidative, wood-aged)",d:"Tawny › Reserve Tawny › Aged Tawny with an indication of age (10 / 20 / 30 / 40 Year) › Colheita (a single-vintage tawny aged in wood)."},
  {n:"Madeira — by grape/sweetness",d:"Sercial (driest) › Verdelho › Bual › Malmsey/Malvasia (sweetest). Age indications 5/10/15/20+ yrs; Frasqueira/Garrafeira = vintage, very long cask aging."},
  {n:"White & Rosé Port",d:"White Port (dry to sweet, served chilled, often with tonic) and Rosé Port."}
 ],
 aging:[
  {t:"Aged Tawny (10/20/30/40 Year)",d:"The number is the approximate AVERAGE age of the blend, not a single vintage."},
  {t:"Garrafeira",d:"In still wine, extended aging (often vintage-dated); in Port, a rare cask-then-bottle style."}
 ],
 terms:[
  {t:"Quinta",d:"Estate/farm — single-quinta Ports come from one estate, often in undeclared years."},
  {t:"Colheita",d:"A single-vintage TAWNY (oxidative, wood-aged). Do not confuse with Vintage Port."},
  {t:"Reserva / Reserva Especial",d:"Indicates extra aging/quality within a style."},
  {t:"Tinto / Branco",d:"Red / white."},
  {t:"Engarrafado na origem",d:"Estate bottled."},
  {t:"Doce / Meio Seco / Seco",d:"Sweet / medium-dry / dry."}
 ],
 traps:[
  "Colheita vs Vintage: BOTH are single-vintage Ports, but Colheita is a wood-aged TAWNY (oxidative) while Vintage Port is a bottle-aged RUBY style — opposite in character.",
  "Tawny age statements (10/20/30/40) are an AVERAGE age, not the wine's exact age.",
  "Madeira's sweetness ladder Sercial→Verdelho→Bual→Malmsey runs driest to sweetest.",
  "Vintage Port is only 'declared' in exceptional years."
 ]},

{name:"Germany",flag:"🇩🇪",
 framework:"TWO parallel systems run at once: (1) the legal Prädikat ladder, ranked by grape RIPENESS (must weight) at harvest, and (2) the VDP growers' association's terroir pyramid. Plus dryness terms. The Grosslage/Einzellage and German-vs-Austrian Kabinett traps live here.",
 pyramid:[
  {t:"Prädikatswein (by ripeness)",d:"Kabinett › Spätlese › Auslese › Beerenauslese (BA) › Eiswein › Trockenbeerenauslese (TBA). Ranked by must weight at harvest, NOT directly by sweetness."},
  {t:"Qualitätswein (QbA)",d:"Quality wine from one region; chaptalization (adding sugar pre-ferment) is allowed."},
  {t:"Landwein",d:"IGP — regional country wine."},
  {t:"Deutscher Wein",d:"Basic table wine."}
 ],
 systems:[
  {n:"VDP pyramid (top growers)",d:"Gutswein (estate) › Ortswein (village) › Erste Lage (premier vineyard) › Grosse Lage (top vineyard). A DRY wine from a Grosse Lage is a Grosses Gewächs (GG)."},
  {n:"Prädikat ladder (ripeness)",d:"Kabinett (lightest) up to TBA. BA, Eiswein and TBA are always sweet, nobly-concentrated dessert wines; Kabinett/Spätlese/Auslese can be dry OR sweet."},
  {n:"2021 origin reform",d:"German law is shifting toward a French-style 'narrower origin = higher quality' pyramid (Region › Ort › Einzellage), aligning with the VDP idea."}
 ],
 aging:[
  {t:"Dryness",d:"Trocken (dry) · Halbtrocken / Feinherb (off-dry) · otherwise often fruity-sweet."}
 ],
 terms:[
  {t:"Einzellage",d:"A SINGLE vineyard."},
  {t:"Grosslage",d:"A COLLECTIVE name bundling many vineyards — sounds site-specific but isn't (e.g. Piesporter Michelsberg)."},
  {t:"Erzeugerabfüllung / Gutsabfüllung",d:"Estate bottled."},
  {t:"Weingut",d:"Wine estate."},
  {t:"Sekt / Winzersekt",d:"Sparkling / grower sparkling."},
  {t:"AP-Nr. (Amtliche Prüfungsnummer)",d:"Official testing number every quality wine must carry."}
 ],
 traps:[
  "Grosslage vs Einzellage: a Grosslage bundles MANY vineyards under a deceptively single-site-sounding name; an Einzellage is one true vineyard.",
  "Grosse Lage (a vineyard CLASSIFICATION) vs Grosses Gewächs (the dry WINE made from it) — site vs wine.",
  "German Kabinett = an off-dry Prädikat (ripeness level). Austrian Kabinett = a DRY quality category. Same word, opposite meaning.",
  "Prädikat measures ripeness (must weight) at harvest, not sweetness directly — a Trocken Spätlese is dry."
 ]},

{name:"Austria",flag:"🇦🇹",
 framework:"Tiers: Wein › Landwein › Qualitätswein (which INCLUDES the dry Kabinett category) › Prädikatswein (sweet). Layered on top is the DAC system for regional typicity, and the Wachau's own ripeness tiers. Most Austrian wine is bone dry.",
 pyramid:[
  {t:"Prädikatswein (sweet)",d:"Ripeness ladder like Germany: Spätlese › Auslese › Beerenauslese › Eiswein › Ausbruch (a Rust specialty) › TBA."},
  {t:"Qualitätswein",d:"Includes KABINETT as a capped, DRY category (not a Prädikat as in Germany)."},
  {t:"Landwein",d:"IGP — regional wine."},
  {t:"Wein",d:"Basic table wine."}
 ],
 systems:[
  {n:"DAC (Districtus Austriae Controllatus)",d:"Origin appellations built on TYPICITY (e.g. Weinviertel DAC = peppery Grüner Veltliner). Often tiered Gebietswein (region) › Ortswein (village) › Riedenwein (single vineyard / 'Ried')."},
  {n:"Wachau — Vinea Wachau tiers",d:"By ripeness/alcohol: Steinfeder (lightest) › Federspiel (medium) › Smaragd (ripest, fullest)."},
  {n:"Sekt Austria",d:"Tiered traditional-method sparkling: Klassik › Reserve › Grosse Reserve."}
 ],
 aging:[
  {t:"Reserve",d:"Indicates a riper, higher-alcohol, fuller style."},
  {t:"Ausbruch",d:"A Prädikat sweetness level (from Rust) sitting between BA and TBA."}
 ],
 terms:[
  {t:"Ried",d:"A single named vineyard."},
  {t:"DAC",d:"Regional-typicity appellation."},
  {t:"Gemischter Satz",d:"A FIELD BLEND — co-planted, co-harvested varieties; a Vienna (Wien) specialty and its own DAC."},
  {t:"Trocken",d:"Dry (the default style in Austria)."},
  {t:"Smaragd / Federspiel / Steinfeder",d:"Wachau ripeness tiers (Smaragd = ripest)."}
 ],
 traps:[
  "Austrian Kabinett = a DRY Qualitätswein category (capped sugar/alcohol) — the OPPOSITE of Germany's off-dry Kabinett Prädikat.",
  "Wachau tiers Steinfeder < Federspiel < Smaragd run light → ripe/full.",
  "Gemischter Satz is a co-planted field blend, strongly tied to Vienna.",
  "Ausbruch is a specific sweet Prädikat level associated with Rust."
 ]},

{name:"United States",flag:"🇺🇸",
 framework:"There is NO European-style quality classification. An AVA states ORIGIN only — no grape, yield or method rules. What actually matters on a US label is the set of PERCENTAGE rules, and the fact that 'Reserve' is meaningless.",
 pyramid:[
  {t:"AVA (American Viticultural Area)",d:"A delimited grape-growing area (e.g. Napa Valley). AVAs nest (Napa Valley › Oakville). Origin only — implies nothing about quality."},
  {t:"County / State appellation",d:"Broader origin claims (e.g. 'California', 'Sonoma County')."},
  {t:"American (multi-state)",d:"Grapes from more than one state."}
 ],
 systems:[
  {n:"Varietal labeling",d:"≥75% of the named grape (federal). Oregon is stricter at 90% for most varieties (Cabernet Sauvignon is an exception)."},
  {n:"Appellation of origin",d:"≥85% of grapes from a named AVA (≥75% for a county). 'Estate Bottled' requires 100% from the winery's own vineyards within that AVA, vinified and bottled on site."},
  {n:"Vintage",d:"≥95% from the stated year for an AVA wine (85% for a broader appellation)."},
  {n:"Meritage",d:"A trademarked term for a Bordeaux-style blend (no single grape reaches the 75% varietal minimum)."}
 ],
 terms:[
  {t:"Estate Bottled",d:"Winery grew (or controls) the grapes within the AVA and made the wine on site."},
  {t:"Produced and bottled by",d:"The winery made ≥75% of the wine — a stronger claim than 'Cellared/Vinted by'."},
  {t:"Reserve / Old Vine / Barrel Select",d:"UNREGULATED marketing terms in the US."},
  {t:"Meritage",d:"Bordeaux-style blend (trademark)."}
 ],
 traps:[
  "'Reserve', 'Old Vine' and 'Barrel Select' are legally MEANINGLESS in the US — pure marketing (contrast Spain's Reserva / Italy's Riserva).",
  "An AVA tells you WHERE, not the grape or the quality.",
  "Federal varietal minimum is 75%; Oregon raises it to 90% for most grapes.",
  "'Produced and bottled by' (≥75% made there) outranks 'Cellared by' or 'Vinted by'."
 ]},

{name:"Australia",flag:"🇦🇺",
 framework:"Origin is handled by GIs (Geographic Indications) — like AVAs, origin only, no quality tier. The label rules to know are the 85% rule and how blends are ordered. The one prestige 'ranking' (Langton's) is private, not legal.",
 pyramid:[
  {t:"GI — Region",d:"e.g. Barossa Valley, Margaret River — the working unit."},
  {t:"GI — Zone",d:"A grouping of regions (e.g. Mount Lofty Ranges)."},
  {t:"GI — State / 'South Eastern Australia'",d:"Broad multi-region blends."}
 ],
 systems:[
  {n:"The 85% rule (Label Integrity Program)",d:"A stated variety, region or vintage must each be ≥85% true."},
  {n:"Blend ordering",d:"Multi-variety blends are listed in DESCENDING order — 'Shiraz Cabernet' has more Shiraz than Cabernet."},
  {n:"Langton's Classification",d:"A respected PRIVATE, market-based ranking of Australia's most collectible wines (Exceptional, Outstanding, Excellent) — not a government system."}
 ],
 terms:[
  {t:"GI",d:"Geographic Indication — origin only."},
  {t:"Shiraz",d:"Australia's name for Syrah."},
  {t:"Old Vine / Old Bush Vine",d:"Unregulated descriptors."},
  {t:"Show Reserve",d:"Marketing term referencing wine-show success."}
 ],
 traps:[
  "A blend like 'Shiraz Cabernet' lists grapes by proportion — most-used grape first.",
  "A GI is origin only; there is no legal quality classification.",
  "Langton's Classification is private/commercial, not an official ranking.",
  "'Shiraz' = Syrah."
 ]},

{name:"New Zealand",flag:"🇳🇿",
 framework:"Origin via GIs under the Geographical Indications Act; an 85% rule governs variety, vintage and region. No formal quality tiers — reputation is style- and region-driven (e.g. Marlborough Sauvignon Blanc).",
 pyramid:[
  {t:"GI — Region",d:"e.g. Marlborough, Central Otago, Hawke's Bay."},
  {t:"GI — broader / New Zealand",d:"Multi-region or national blends."}
 ],
 systems:[
  {n:"The 85% rule",d:"A stated variety, vintage or GI must be ≥85% (often higher in practice)."},
  {n:"Single Vineyard / Estate",d:"Used to signal quality but only lightly regulated."}
 ],
 terms:[
  {t:"GI",d:"Geographical Indication — origin only."},
  {t:"Single Vineyard",d:"From one named vineyard (lightly regulated)."},
  {t:"Méthode Traditionnelle",d:"Traditional-method sparkling."}
 ],
 traps:[
  "GI = origin; there is no legal quality hierarchy.",
  "Marlborough Sauvignon Blanc is defined by STYLE/region, not a classification tier.",
  "Stated variety/vintage/region must be ≥85%."
 ]},

{name:"South Africa",flag:"🇿🇦",
 framework:"The Wine of Origin (WO) scheme certifies origin, vintage and variety, guaranteed by a numbered seal on the bottle. Estate and Single-Vineyard categories add a quality signal; Cap Classique is the sparkling term to know.",
 pyramid:[
  {t:"Ward",d:"Smallest WO unit — a specific local area."},
  {t:"District",d:"e.g. Stellenbosch, Paarl."},
  {t:"Region",d:"e.g. Coastal Region."},
  {t:"Geographical Unit",d:"Broadest (e.g. Western Cape)."}
 ],
 systems:[
  {n:"Wine of Origin (WO) certification",d:"A stated WO area must be 100% true; stated variety and vintage must be ≥85%. A certification seal guarantees it."},
  {n:"Estate Wine",d:"From a registered single estate — grapes grown, wine made AND bottled there."},
  {n:"Single Vineyard",d:"From one registered vineyard (≤6 ha)."},
  {n:"Méthode Cap Classique (MCC)",d:"South Africa's term for traditional-method (bottle-fermented) sparkling wine."}
 ],
 terms:[
  {t:"WO (Wine of Origin)",d:"Certified origin scheme."},
  {t:"Estate Wine",d:"Grown, made and bottled on one registered estate."},
  {t:"Cap Classique / MCC",d:"Traditional-method sparkling."},
  {t:"Pinotage",d:"South Africa's signature grape (Pinot Noir × Cinsault)."}
 ],
 traps:[
  "'Méthode Cap Classique' (MCC) = South African traditional-method sparkling.",
  "A WO origin claim means 100% from that stated area.",
  "Stated variety/vintage must be ≥85%."
 ]},

{name:"Argentina",flag:"🇦🇷",
 framework:"A DOC system exists but is minor (only a couple of zones); most labels work by region (IG) plus variety, and altitude is often highlighted. 'Reserva' is loosely used — not strictly regulated nationally.",
 pyramid:[
  {t:"DOC",d:"Denominación de Origen Controlada — only a few zones (Luján de Cuyo, San Rafael)."},
  {t:"IG (Indicación Geográfica)",d:"Geographic indication — provinces/departments (Mendoza, Uco Valley, etc.). The main working unit."},
  {t:"Wines without IG",d:"Basic/varietal wines."}
 ],
 systems:[
  {n:"Region + variety labeling",d:"Most Argentine wine is sold by region and grape (e.g. 'Uco Valley Malbec') rather than by classification."},
  {n:"Altitude as a cue",d:"Elevation (metres above sea level) often appears on labels as a climate/quality signal — high sites = cool nights, fresher wines."}
 ],
 terms:[
  {t:"Bodega",d:"Winery."},
  {t:"Finca",d:"Estate/vineyard (often a single named site)."},
  {t:"Reserva",d:"Used to suggest extra aging/quality, but loosely defined."},
  {t:"Corte",d:"A blend."},
  {t:"Viñas Viejas",d:"Old vines."}
 ],
 traps:[
  "Argentine 'Reserva' is loosely defined — not a strict legal tier like Spain's.",
  "DOC is minor; region (IG) + variety dominates labelling.",
  "Altitude (m.a.s.l.) on the label is a climate cue, not a legal classification."
 ]},

{name:"Chile",flag:"🇨🇱",
 framework:"Origin is set by DO (Denominación de Origen) valleys, plus the cross-cutting climate terms Costa / Entre Cordilleras / Andes. A 75% rule governs stated variety/vintage/origin. 'Reserva' tiers exist in law but are only weakly demanding.",
 pyramid:[
  {t:"DO — Valley/Sub-region",d:"e.g. Maipo, Colchagua, Casablanca — the working origin unit."},
  {t:"DO — Region",d:"e.g. Valle Central."},
  {t:"Without DO",d:"Basic wines."}
 ],
 systems:[
  {n:"Costa / Entre Cordilleras / Andes (2011)",d:"Cross-cutting terms for a wine's position: Costa (coastal/cool), Entre Cordilleras (between the ranges), Andes (foothills). They describe CLIMATE, not quality."},
  {n:"The 75% rule",d:"A stated variety, vintage or origin must be ≥75% (raised to 85% for many export markets, including the EU)."},
  {n:"Reserva tiers (2011)",d:"Reserva, Reserva Especial, Reserva Privada and Gran Reserva exist in law, but with modest requirements (e.g. small alcohol bumps, some oak) — treat them as loose."}
 ],
 terms:[
  {t:"Viña",d:"Winery/vineyard."},
  {t:"DO",d:"Denominación de Origen — origin."},
  {t:"Costa / Andes / Entre Cordilleras",d:"Climate/position terms."},
  {t:"Carménère",d:"Chile's signature grape — long mistaken for Merlot in its vineyards."}
 ],
 traps:[
  "Costa / Entre Cordilleras / Andes are CLIMATE/position terms, not quality tiers.",
  "Chile's 'Reserva' and 'Gran Reserva' exist in law but are only weakly demanding.",
  "Carménère was historically confused with Merlot in Chilean vineyards.",
  "Stated variety/vintage/origin must be ≥75% (often 85% for export)."
 ]}
];

var INTRO_CLASS_TRAPQ=[
{cty:"France",q:"The word ‘Cru’ shifts meaning by region. In Champagne, a ‘Cru’ ranks:",opts:["A whole village (commune)","A single vineyard","An individual estate/château","A grape variety"],a:0,exp:"Champagne ranks villages (Échelle des Crus); Burgundy ranks vineyards; Bordeaux ranks estates."},
{cty:"France",q:"In St-Émilion, a wine labeled simply ‘Grand Cru’ (not ‘Grand Cru Classé’) sits:",opts:["Near the bottom — a broad entry tier","At the very top of the hierarchy","Above Premier Grand Cru Classé","Outside the classification entirely"],a:0,exp:"St-Émilion ‘Grand Cru’ is the broad base tier; the top is Premier Grand Cru Classé A."},
{cty:"France",q:"Which famous Bordeaux district has NO official classification?",opts:["Pomerol","Médoc","Sauternes","Pessac-Léognan"],a:0,exp:"Pomerol (Pétrus, Le Pin) is unclassified."},
{cty:"France",q:"A Burgundy Grand Cru label typically shows:",opts:["Only the vineyard name (e.g. ‘Chambertin’)","Village + ‘1er Cru’ + vineyard","The grape variety","The négociant name only"],a:0,exp:"Grand Cru = the vineyard name alone; Premier Cru shows village + 1er Cru + vineyard."},
{cty:"France",q:"The only change to the 1855 First Growths since 1855 was the 1973 promotion of:",opts:["Château Mouton Rothschild","Château Pétrus","Château Cheval Blanc","Château Palmer"],a:0,exp:"Mouton was elevated from Second to First Growth in 1973."},
{cty:"France",q:"On the Champagne dosage scale, which is SWEETER?",opts:["Extra Dry","Brut","Extra Brut","Brut Nature"],a:0,exp:"Counter-intuitively, ‘Extra Dry’ is sweeter than ‘Brut’."},
{cty:"Italy",q:"Vino Nobile di Montepulciano is made mainly from which grape?",opts:["Sangiovese","Montepulciano","Nebbiolo","Primitivo"],a:0,exp:"Vino Nobile = Sangiovese from the Tuscan town; Montepulciano d'Abruzzo is the grape."},
{cty:"Italy",q:"Montepulciano d'Abruzzo takes its name from:",opts:["The grape variety","A Tuscan town","A classification tier","A producer"],a:0,exp:"Here Montepulciano is the GRAPE; the Tuscan town gives Vino Nobile (Sangiovese)."},
{cty:"Italy",q:"The top tier of Chianti Classico is:",opts:["Gran Selezione","Riserva","Annata","Superiore"],a:0,exp:"Gran Selezione (since 2014) sits above Riserva and Annata."},
{cty:"Italy",q:"The black rooster (Gallo Nero) seal identifies:",opts:["Chianti Classico","Brunello di Montalcino","Barolo","Prosecco"],a:0,exp:"The gallo nero is Chianti Classico's emblem."},
{cty:"Italy",q:"A ‘Super Tuscan’ is most often classified as:",opts:["IGT","DOCG","DOC","Vino da Tavola"],a:0,exp:"Many top Super Tuscans are IGT, bypassing rigid DOC rules — tier ≠ quality."},
{cty:"Spain",q:"Unlike the US term ‘Reserve’, Spain's ‘Reserva’ is:",opts:["A legally defined aging category","An unregulated marketing word","A grape variety","A sweetness level"],a:0,exp:"Reserva/Gran Reserva have legal aging minimums; US ‘Reserve’ does not."},
{cty:"Spain",q:"Spain's top tier (DOCa/DOQ) is held by only which two regions?",opts:["Rioja and Priorat","Rioja and Ribera del Duero","Penedès and Rías Baixas","Jerez and Rueda"],a:0,exp:"Only Rioja (DOCa, 1991) and Priorat (DOQ, 2009)."},
{cty:"Spain",q:"Spanish ‘Gran Reserva’ indicates:",opts:["The longest aging, made only in top vintages","A young wine bottled with little or no oak","A traditional-method sparkling style","A fortified sweet dessert wine"],a:0,exp:"Gran Reserva ≈5 years aging; declared only in strong vintages."},
{cty:"Spain",q:"Cava is best described as:",opts:["A traditional-method sparkling wine (mostly Penedès)","A still red wine from one Catalan town","A fortified wine matured under flor","A sweet, oxidative sherry-style wine"],a:0,exp:"Cava is a DO defined by method/producer, made mainly in Penedès."},
{cty:"Portugal",q:"A ‘Colheita’ Port is:",opts:["A single-vintage TAWNY (wood-aged)","A bottle-aged Vintage (ruby) Port","A white Port","A non-vintage Ruby"],a:0,exp:"Colheita = single-year tawny aged oxidatively in wood — NOT a Vintage Port."},
{cty:"Portugal",q:"From DRIEST to sweetest, the Madeira grapes run:",opts:["Sercial → Verdelho → Bual → Malmsey","Malmsey → Bual → Verdelho → Sercial","Bual → Sercial → Malmsey → Verdelho","Verdelho → Sercial → Bual → Malmsey"],a:0,exp:"Sercial (driest) → Verdelho → Bual → Malmsey/Malvasia (sweetest)."},
{cty:"Portugal",q:"Vintage Port is produced:",opts:["Only in exceptional, ‘declared’ years","Every single year","Only from white grapes","Only as a tawny style"],a:0,exp:"Vintage Port is declared only in the best years and ages in bottle."},
{cty:"Germany",q:"A German ‘Grosslage’ on a label is:",opts:["A collective name bundling many vineyards","A single, specific vineyard","An estate-bottling term","A sweetness level"],a:0,exp:"Grosslage bundles many sites under a deceptively single-site-sounding name; Einzellage is one vineyard."},
{cty:"Germany",q:"German ‘Kabinett’ is:",opts:["The lightest Prädikat (a ripeness level)","A dry quality category","A sparkling wine","A vineyard classification"],a:0,exp:"German Kabinett is the lightest Prädikat (ripeness); in AUSTRIA, Kabinett is a DRY category."},
{cty:"Germany",q:"A ‘Grosses Gewächs (GG)’ is:",opts:["A dry wine from a top (Grosse Lage) vineyard","Only a vineyard classification","A sweet dessert wine","A sparkling Sekt"],a:0,exp:"Grosse Lage = the site; Grosses Gewächs = the dry wine from it."},
{cty:"Austria",q:"Austrian ‘Kabinett’ differs from German Kabinett because it is:",opts:["A dry quality category","An off-dry Prädikat","A sweet dessert wine","A sparkling style"],a:0,exp:"Austrian Kabinett is a capped, DRY Qualitätswein category — opposite of Germany's off-dry Prädikat."},
{cty:"Austria",q:"In the Wachau, which tier is the ripest and fullest?",opts:["Smaragd","Federspiel","Steinfeder","Kabinett"],a:0,exp:"Steinfeder (light) < Federspiel (medium) < Smaragd (ripest)."},
{cty:"Austria",q:"‘Gemischter Satz’, a Vienna specialty, is:",opts:["A co-planted field blend","A single-variety Grüner Veltliner","A sweet wine","A sparkling method"],a:0,exp:"Gemischter Satz = field blend (co-planted, co-harvested), a Wiener DAC."},
{cty:"United States",q:"On a US label, ‘Reserve’ legally means:",opts:["Nothing — it's unregulated marketing","A minimum of 3 years aging","100% estate-grown fruit","A government quality tier"],a:0,exp:"US ‘Reserve’, ‘Old Vine’ and ‘Barrel Select’ are unregulated — unlike EU equivalents."},
{cty:"United States",q:"A US varietal wine must contain at least how much of the named grape (federal rule)?",opts:["75%","85%","95%","100%"],a:0,exp:"Federal minimum is 75% (Oregon raises it to 90% for most grapes)."},
{cty:"United States",q:"An American Viticultural Area (AVA) guarantees:",opts:["Where the grapes were grown (origin only)","A government-set minimum quality level","The grape variety inside the bottle","A legal maximum vineyard yield"],a:0,exp:"An AVA is origin only — no quality, grape or yield rules."},
{cty:"Australia",q:"An Australian wine labeled ‘Shiraz Cabernet’ contains:",opts:["More Shiraz than Cabernet","More Cabernet than Shiraz","Exactly equal parts","Only Shiraz"],a:0,exp:"Blends are listed in descending order — the most-used grape comes first."},
{cty:"Australia",q:"Langton's Classification of Australian Wine is:",opts:["A private, market-based ranking","A government classification","A legal aging requirement","A regional boundary system"],a:0,exp:"Langton's is a respected private/commercial ranking, not an official one."},
{cty:"South Africa",q:"‘Méthode Cap Classique’ (MCC) refers to:",opts:["South African traditional-method sparkling","A South African sweet wine","A grape variety","An origin seal"],a:0,exp:"MCC = bottle-fermented (traditional-method) sparkling from South Africa."},
{cty:"South Africa",q:"A South African ‘Wine of Origin’ (WO) area claim guarantees it is:",opts:["100% true","at least 75% true","at least 50% true","unregulated"],a:0,exp:"WO origin = 100%; stated variety/vintage must be ≥85%."},
{cty:"Chile",q:"On a Chilean label, ‘Costa’, ‘Entre Cordilleras’ and ‘Andes’ indicate:",opts:["Climate/position: coast, between ranges, foothills","Official government quality tiers","Minimum barrel-aging categories","The permitted grape varieties"],a:0,exp:"They describe a wine's position/climate, not quality."},
{cty:"Chile",q:"In Chile, which grape was long mistaken for Merlot in the vineyards?",opts:["Carménère","Cabernet Franc","Syrah","País"],a:0,exp:"Carménère was widely confused with Merlot in Chile until the 1990s."},
{cty:"Argentina",q:"On an Argentine label, ‘Reserva’ is:",opts:["Loosely defined (not a strict legal tier)","A strict 5-year aging rule","A sparkling category","A single-vineyard term"],a:0,exp:"Argentina's ‘Reserva’ is loosely used, unlike Spain's legally-defined Reserva."}
];

/* ============ Winemaking reference ============
   Topic-based study reference: core process, style forks, and signature
   techniques tagged with WHERE they happen. flow=ordered steps, tech={n,d,w(where)}. */
var INTRO_WINE=[
{name:"The Core Process",ic:"🍇",tag:"grape → bottle, in order",
 intro:"The backbone every wine shares. The decisive fork: WHITE is pressed before fermenting (juice only), while RED ferments ON its skins and is pressed afterward.",
 flow:[
  {t:"Harvest",d:"Picking by hand or machine at the chosen sugar/acid ripeness. Timing sets potential alcohol, acidity and flavour; cool-climate fruit is picked earlier for freshness."},
  {t:"Sorting & destemming",d:"Removing leaves, unripe or rotten fruit and (usually) stems. Keeping stems = 'whole-cluster', which adds structure and aromatics."},
  {t:"Crushing / pressing",d:"WHITE: pressed first so only juice ferments (minimal skin contact). RED: gently crushed and fermented WITH the skins, then pressed AFTER fermentation."},
  {t:"Fermentation",d:"Yeast converts sugar into alcohol + CO₂ (and heat). Cool and slow for aromatic whites; warmer for reds to aid extraction. Runs dry unless stopped."},
  {t:"Maceration (reds)",d:"Skin contact during/after fermentation extracts colour, tannin and flavour. The floating 'cap' of skins is worked by punch-downs or pump-overs."},
  {t:"Pressing & racking",d:"Free-run and press wine are separated; the wine is drawn off its gross lees (sediment)."},
  {t:"Malolactic conversion (MLF)",d:"Bacteria turn sharp malic acid into softer lactic acid — standard for reds and many Chardonnays (can add buttery notes); often blocked for crisp aromatic whites."},
  {t:"Élevage / aging",d:"Maturation in stainless steel, oak, concrete or amphora. Oak adds aroma and slow oxygen; lees aging adds texture. Length varies enormously."},
  {t:"Fining & filtration",d:"Clarifying and stabilising (e.g. bentonite, egg white) and filtering for clarity — some producers skip this for texture ('unfined / unfiltered')."},
  {t:"Blending & bottling",d:"Assembling lots, varieties or vintages, final adjustments, then bottling — still wines under inert gas, or with bottle conditioning."}
 ],
 traps:[
  "White is PRESSED before fermentation (juice only); red FERMENTS on the skins and is pressed afterward — the core red/white fork.",
  "MLF lowers acidity and softens texture (and can add buttery diacetyl) — it has nothing to do with sweetness.",
  "Fermentation makes alcohol FROM sugar; it never adds sugar. Sweet wines RETAIN sugar by stopping fermentation early or concentrating the grapes."
 ]},

{name:"How It Forks by Style",ic:"🎨",tag:"red · white · rosé · sparkling · sweet · fortified",
 intro:"Same toolkit, different sequence. The decisive choices are skin contact, fermentation temperature/vessel, whether MLF happens, and how (or whether) fermentation is stopped.",
 terms:[
  {t:"Red",d:"Ferments ON the skins (maceration) for colour and tannin; pressed after; usually goes through MLF; often oak-aged."},
  {t:"White",d:"Pressed first, then the JUICE ferments (cool temps) to keep aromatics; MLF optional; stainless or oak."},
  {t:"Rosé",d:"Brief skin contact (hours) then press — the maceration method — or 'saignée' (bleeding pink juice off a red must). Then fermented like a white."},
  {t:"Sparkling (traditional)",d:"A still base wine undergoes a SECOND fermentation in the bottle to make the bubbles; aged on lees, then riddled and disgorged."},
  {t:"Sweet",d:"Sugar is concentrated (botrytis, drying, freezing or late harvest) and/or fermentation is STOPPED early so sugar remains."},
  {t:"Fortified",d:"Grape spirit is added: before fermentation finishes = sweet (Port); after it finishes dry = a Sherry base."},
  {t:"Orange (skin-contact white)",d:"White grapes fermented ON their skins like a red — gaining colour, tannin and texture (e.g. Friuli, Georgia)."}
 ],
 traps:[
  "Rosé is usually short skin-contact then press (or saignée) — NOT (in quality wine) red + white blended; that blend is a special legal exception in Champagne.",
  "'Orange' wine is a white made like a red (on the skins) — not a sweet or oxidised style by definition."
 ]},

{name:"Signature Techniques & Where",ic:"📍",tag:"unique steps mapped to regions",
 intro:"The headline 'where does this happen' material. Each technique below is paired with the region or wine it defines.",
 tech:[
  {n:"Carbonic maceration",d:"Whole, uncrushed clusters ferment intracellularly under CO₂ → bright fruit, very low tannin, candied/banana notes.",w:"Beaujolais (Gamay)"},
  {n:"Appassimento (passito)",d:"Grapes dried on mats or racks for weeks to months, concentrating sugar and flavour before fermenting.",w:"Veneto — Amarone & Recioto della Valpolicella"},
  {n:"Ripasso",d:"Valpolicella re-fermented over the leftover Amarone skins for extra body and alcohol — a 'baby Amarone'.",w:"Veneto — Valpolicella Ripasso"},
  {n:"Governo",d:"Adding a little dried-grape must to restart/boost fermentation, softening and rounding the wine.",w:"Tuscany (traditional Chianti)"},
  {n:"Méthode traditionnelle (champenoise)",d:"Second fermentation IN the bottle; lees autolysis (brioche); riddling; disgorgement; dosage.",w:"Champagne — also Cava, Crémant, Franciacorta, Cap Classique"},
  {n:"Tank / Charmat method",d:"Second fermentation in a pressurised TANK, then bottled under pressure — keeps fresh, fruity, floral character.",w:"Prosecco (Glera), Lambrusco"},
  {n:"Méthode ancestrale (pét-nat)",d:"A single fermentation finished in the bottle (no added liqueur) — lightly sparkling, often cloudy.",w:"Limoux (Blanquette), Bugey-Cerdon, Gaillac"},
  {n:"Solera (fractional blending)",d:"Tiered barrels: wine is drawn from the oldest tier and topped up from younger wine, perpetually blending vintages.",w:"Jerez (Sherry) — also Madeira"},
  {n:"Flor (biological aging)",d:"A film of living yeast grows on the wine, shielding it from oxygen and adding tangy, saline, nutty notes.",w:"Jerez — Fino & Manzanilla Sherry"},
  {n:"Oxidative aging",d:"Deliberate air exposure over years → amber colour and nutty, caramel flavours.",w:"Oloroso Sherry, Tawny Port, Madeira"},
  {n:"Estufagem / Canteiro",d:"Madeira is HEATED — quickly in tanks (estufagem) or slowly in warm lofts (canteiro) — giving its baked, tangy character.",w:"Madeira (Portugal)"},
  {n:"Mutage (fortification)",d:"Adding grape spirit to STOP fermentation, leaving natural grape sweetness.",w:"Port; Vins Doux Naturels — Banyuls, Maury, Beaumes-de-Venise"},
  {n:"Sur lie",d:"Aging on the spent yeast (lees) without racking → texture, subtle yeastiness and a slight prickle.",w:"Muscadet (Loire) — also white Burgundy"},
  {n:"Bâtonnage (lees stirring)",d:"Stirring the lees back into the wine for a richer, creamier texture.",w:"White Burgundy (barrel-aged Chardonnay)"},
  {n:"Botrytis (noble rot)",d:"Botrytis cinerea shrivels grapes, concentrating sugar and adding honey, apricot and ginger complexity.",w:"Sauternes, Tokaji Aszú, German BA/TBA, Loire (Quarts de Chaume)"},
  {n:"Eiswein / Icewine",d:"Grapes frozen ON THE VINE are pressed while still frozen; water stays as ice, the juice is intensely sweet.",w:"Germany, Austria — Canada (Icewine)"},
  {n:"Co-fermentation",d:"Fermenting a little white grape together with red for aromatics and colour stabilisation.",w:"Côte-Rôtie (Syrah + up to ~20% Viognier)"},
  {n:"Whole-cluster / stem inclusion",d:"Fermenting with the stems for added structure, spice and floral lift.",w:"Burgundy & N. Rhône (Pinot Noir, Syrah)"},
  {n:"Skin-contact in clay (qvevri)",d:"White grapes fermented on skins in buried clay vessels → 'orange' wine, the world's oldest method.",w:"Georgia (qvevri); Friuli (Italy)"},
  {n:"Vin de paille (straw wine)",d:"Grapes dried on straw mats to concentrate sugar for a sweet wine.",w:"Jura — also N. Rhône (Hermitage)"}
 ],
 traps:[
  "Carbonic maceration = Beaujolais (Gamay): whole-bunch, under CO₂, low tannin, bubblegum/banana.",
  "Solera = FRACTIONAL BLENDING across vintages — which is why most Sherry is non-vintage.",
  "Flor (biological aging) = Fino/Manzanilla; oxidative aging (no flor) = Oloroso; Amontillado starts under flor, THEN turns oxidative.",
  "Eiswein grapes freeze NATURALLY on the vine — freezing picked grapes artificially is 'cryoextraction', not allowed for German Eiswein.",
  "Madeira's defining step is deliberate HEATING (estufagem/canteiro) — unique among the world's great wines."
 ]},

{name:"Sparkling Methods",ic:"🥂",tag:"how the bubbles get in",
 intro:"How the CO₂ is captured defines the style: the traditional method builds complexity (brioche) through bottle fermentation and lees aging; the tank method keeps wines fresh and fruity.",
 flow:[
  {t:"Base wine",d:"A still, high-acid, fairly neutral base is made — often blended across grapes, villages and vintages."},
  {t:"Tirage",d:"Bottled with 'liqueur de tirage' (yeast + sugar) to trigger a SECOND fermentation inside the bottle."},
  {t:"Second fermentation",d:"Yeast produces alcohol + CO₂; trapped under the crown cap, the CO₂ dissolves into the wine as bubbles."},
  {t:"Lees aging (autolysis)",d:"Months to years resting on the dead yeast develops brioche, biscuit and toast complexity."},
  {t:"Riddling (remuage)",d:"Bottles are gradually tilted and turned so the lees slide into the neck."},
  {t:"Disgorgement (dégorgement)",d:"The neck is frozen and the plug of lees is ejected under pressure."},
  {t:"Dosage",d:"Topped up with 'liqueur d'expédition' (wine + sugar) — this sets the final sweetness. Scale (g/L): Brut Nature 0–3 · Extra Brut 0–6 · Brut 0–12 · Extra Dry 12–17 · Sec 17–32 · Demi-Sec 32–50 · Doux 50+."}
 ],
 terms:[
  {t:"Tank (Charmat) method",d:"Second fermentation in a pressurised tank → Prosecco, Lambrusco; fresh and fruity, no autolysis character."},
  {t:"Ancestral method (pét-nat)",d:"A single fermentation finished in the bottle; bottled before it ends, no disgorgement."},
  {t:"Transfer method",d:"Bottle-fermented, then emptied into a pressurised tank, filtered and re-bottled."},
  {t:"Carbonation",d:"CO₂ simply injected — the cheapest method, with the coarsest bubbles."}
 ],
 traps:[
  "Traditional method = 2nd fermentation IN THE BOTTLE + lees autolysis (brioche); tank/Charmat method = in a tank (fresh, fruity Prosecco).",
  "Dosage is the final sugar addition that sets dryness — and remember Extra Dry is sweeter than Brut."
 ]},

{name:"Sweet Wine Methods",ic:"🍯",tag:"where the sugar comes from",
 intro:"Every sweet wine either CONCENTRATES sugar in the grape or STOPS fermentation before the yeast eats it all. Here are the routes and where each is famous.",
 tech:[
  {n:"Noble rot (botrytis)",d:"The fungus shrivels ripe grapes, concentrating sugar and adding honey, saffron and apricot complexity.",w:"Sauternes, Tokaji Aszú, German/Austrian BA & TBA, Loire"},
  {n:"Late harvest",d:"Grapes left to over-ripen and partially raisin on the vine, gaining sugar.",w:"Alsace Vendange Tardive, German Spätlese/Auslese, New World 'Late Harvest'"},
  {n:"Ice wine (Eiswein)",d:"Naturally frozen grapes pressed while frozen; the sweet juice runs off, the ice stays behind.",w:"Germany, Austria, Canada"},
  {n:"Dried-grape (passito / appassimento)",d:"Grapes air-dried to raisins before fermenting, concentrating everything.",w:"Recioto (Veneto), Vin Santo (Tuscany), straw wine (Jura)"},
  {n:"Fortification (mutage)",d:"Spirit added mid-fermentation to halt the yeast, keeping natural sweetness.",w:"Port, Vins Doux Naturels (Beaumes-de-Venise, Banyuls)"}
 ],
 traps:[
  "Botrytis here means NOBLE rot (beneficial, concentrating); ordinary 'grey rot' on healthy grapes is a fault.",
  "Eiswein/Icewine concentrates sugar by FREEZING on the vine — not by drying (that's passito) or by fungus (that's botrytis)."
 ]},

{name:"Fortified & Oxidative",ic:"🥃",tag:"spirit, flor & solera",
 intro:"Fortified wines add grape spirit. WHEN the spirit goes in sets the sweetness; HOW the wine is then aged (under protective flor, or exposed to air) sets the style.",
 tech:[
  {n:"Fortify before fermentation ends",d:"Halts fermentation with sugar remaining → a SWEET fortified wine.",w:"Port, Vin Doux Naturel"},
  {n:"Fortify after fermentation (dry)",d:"All sugar already fermented, so the base is DRY before aging.",w:"Sherry (Fino, Oloroso)"},
  {n:"Flor / biological aging",d:"A yeast film shields the wine from oxygen → pale, tangy, saline, low-oxidation style.",w:"Fino & Manzanilla (Jerez / Sanlúcar)"},
  {n:"Oxidative aging",d:"Air exposure over years → amber colour, nutty, caramelised flavours.",w:"Oloroso Sherry, Tawny Port, Madeira"},
  {n:"Solera system",d:"Fractional blending up through tiers of barrels → a consistent non-vintage house style.",w:"Sherry; Madeira"},
  {n:"Estufagem / Canteiro",d:"Heating the wine — fast in tanks (estufagem) or slowly in warm lofts (canteiro) — for Madeira's baked tang.",w:"Madeira"}
 ],
 traps:[
  "Fino/Manzanilla = biological (flor) aging, pale and tangy; Oloroso = oxidative, dark and nutty; Amontillado = flor FIRST, then oxidative.",
  "Sweet Sherry styles (e.g. Cream) are usually sweetened AFTER aging — the base Sherry ferments fully dry."
 ]},

{name:"Cap Management & Extraction",ic:"🔄",tag:"working the red must",
 intro:"During red fermentation the skins float up into a 'cap'. How you mix that cap back into the juice governs how much colour and tannin you extract.",
 terms:[
  {t:"Pigeage (punch-down)",d:"Pushing the cap down into the juice by hand or tool — gentle, even extraction."},
  {t:"Remontage (pump-over)",d:"Pumping juice up and over the cap — extraction plus oxygen and temperature control."},
  {t:"Délestage (rack & return)",d:"Draining the wine off the skins, then returning it over the cap — softer tannins, even mixing."},
  {t:"Cold soak (pre-ferment maceration)",d:"Chilling the must before fermentation to draw colour/aroma without alcohol — classic for Pinot Noir."},
  {t:"Extended maceration",d:"Leaving the wine on skins after fermentation so tannins polymerise and soften — common for Cabernet."},
  {t:"Saignée",d:"'Bleeding off' some pink juice early — it makes a rosé AND concentrates the red left behind."}
 ],
 traps:[
  "Pigeage = punch DOWN; remontage = pump OVER — both manage the floating cap of skins.",
  "Cold soak happens BEFORE fermentation (no alcohol yet); extended maceration happens AFTER fermentation."
 ]},

{name:"Aging & Vessels",ic:"🛢️",tag:"élevage choices",
 intro:"After fermentation the vessel shapes texture and flavour: oak adds aroma and slow oxygen, while inert vessels preserve primary fruit.",
 terms:[
  {t:"New vs old oak",d:"New oak adds vanilla, spice and toast; older/neutral oak mainly allows gentle oxygen with little added flavour."},
  {t:"Barrique vs botte / foudre",d:"A small 225L barrique gives more oak influence; large old botti/foudres give little flavour and gentle oxygen (the Barolo tradition)."},
  {t:"Stainless steel",d:"Inert and temperature-controlled — preserves fresh, primary fruit (e.g. Sauvignon Blanc)."},
  {t:"Concrete egg / amphora",d:"Micro-oxygenation without oak flavour; builds texture and purity (amphora/qvevri also used for skin-contact whites)."},
  {t:"Lees aging & bâtonnage",d:"Time on, or stirring of, the lees builds body, creaminess and complexity."},
  {t:"Micro-oxygenation",d:"Tiny controlled doses of oxygen to soften tannins and stabilise colour."}
 ],
 traps:[
  "Large old 'botti'/foudres impart LITTLE oak flavour (mostly gentle oxygen); small NEW barriques impart the most.",
  "Stainless steel preserves primary fruit; oak adds aroma, texture and slow oxidation."
 ]}
];

/* ============ Soil & Terroir reference ============
   Topic-based reference: terroir components + major soil types, each mapped to the
   grapes/wines and regions that thrive in it. Same schema as WINE (tech={n,d,w(where)}). */
var INTRO_SOIL=[
{name:"What is Terroir?",ic:"🌍",tag:"the sense of place",
 intro:"Terroir is the whole natural environment a vine grows in — soil, climate, topography and aspect — that gives a wine its sense of place. Soil gets the most attention, but climate and slope often matter more for whether grapes even ripen.",
 terms:[
  {t:"Soil",d:"Controls drainage, water-holding, heat retention and nutrients. Poorer soils that stress the vine generally make better wine than rich, fertile ones."},
  {t:"Climate (macro)",d:"Cool vs warm region — sets ripeness, acidity and which grapes can ripen there at all."},
  {t:"Mesoclimate & aspect",d:"A specific slope's exposure: south-facing sites (Northern Hemisphere) catch more sun; slopes also drain cold air and water."},
  {t:"Topography",d:"Altitude (cool nights, big diurnal swing), slope (drainage, sun angle) and nearness to water (moderation, fog, frost protection)."},
  {t:"The human element",d:"Grape choice, training, yields and winemaking — increasingly considered part of terroir too."}
 ],
 traps:[
  "Vines thrive in POOR, well-drained soils — fertility and vigour are the enemy of quality, because stress concentrates the fruit.",
  "'Minerality' is a tasting term; a literal soil-to-flavour transfer is debated, but soil's effect on drainage, warmth and vine vigour is very real."
 ]},

{name:"Limestone & Chalk",ic:"⚪",tag:"acidity, finesse, great whites",
 intro:"Alkaline, calcium-rich soils that hold water yet drain well, reflect light, and are linked to high acidity and 'minerality'. The classic home of Chardonnay, Pinot Noir and Chenin Blanc.",
 tech:[
  {n:"Chardonnay & Pinot Noir",d:"Limestone and marl slopes give finesse, bright acidity and ageability.",w:"Burgundy (Côte d'Or); Champagne (chalk)"},
  {n:"Chardonnay",d:"Kimmeridgian limestone (fossil-rich marl) gives steely, mineral whites.",w:"Chablis"},
  {n:"Sauvignon Blanc",d:"Kimmeridgian limestone with flint (silex) → flinty, mineral whites.",w:"Sancerre & Pouilly-Fumé (Loire)"},
  {n:"Chenin Blanc & Cabernet Franc",d:"Soft 'tuffeau' chalk gives fresh, age-worthy wines.",w:"Vouvray, Chinon (Loire)"},
  {n:"Palomino (Sherry)",d:"Brilliant-white 'albariza' chalk stores winter rain through hot, dry summers.",w:"Jerez (Spain)"},
  {n:"Nebbiolo",d:"Calcareous marl gives perfumed, structured, age-worthy reds.",w:"Barolo & Barbaresco (Piedmont)"}
 ],
 traps:[
  "Chablis sits on Kimmeridgian limestone full of marine fossils — a classic exam fact.",
  "Jerez's chalky 'albariza' soil acts like a sponge, banking winter rain for the vine."
 ]},

{name:"Slate & Schist",ic:"🟫",tag:"heat, drainage, Riesling",
 intro:"Layered, stony metamorphic soils that drain freely and absorb and radiate heat — helping ripen grapes on steep, cool or poor sites. Famous for Riesling and for powerful southern reds.",
 tech:[
  {n:"Riesling",d:"Blue and red Devonian slate on steep slopes radiates stored heat, giving racy, mineral wines.",w:"Mosel (Germany)"},
  {n:"Garnacha & Cariñena",d:"'Llicorella' — brown slate flecked with quartz — forces roots deep for powerful, mineral reds.",w:"Priorat (Spain)"},
  {n:"Touriga Nacional & Port grapes",d:"Schist (xisto) on steep terraces; vines dig deep for water.",w:"Douro Valley (Portugal)"}
 ],
 traps:[
  "Mosel Riesling on slate: the dark stones store the day's heat — vital in a cool, high-latitude region.",
  "Priorat's signature soil is 'llicorella' slate; the Douro's is schist."
 ]},

{name:"Granite",ic:"🪨",tag:"warmth, Gamay & Syrah",
 intro:"Coarse, free-draining, low-fertility rock that warms quickly and stresses the vine. Linked to aromatic, structured reds and some crisp whites.",
 tech:[
  {n:"Gamay",d:"Granite and pink-granite sands give the Cru Beaujolais their structure and perfume.",w:"Cru Beaujolais (Morgon, Fleurie, Moulin-à-Vent)"},
  {n:"Syrah",d:"Steep granite hillsides give intense, structured, age-worthy Syrah.",w:"Northern Rhône — Hermitage, Côte-Rôtie"},
  {n:"Touriga Nacional & Encruzado",d:"Granite-based soils give fresh, structured Dão reds and whites.",w:"Dão (Portugal)"}
 ],
 traps:[
  "Northern-Rhône Hermitage and Côte-Rôtie sit on granite (Syrah); the Cru Beaujolais also prize granite (Gamay)."
 ]},

{name:"Gravel & Stones",ic:"🟤",tag:"drainage, heat, late-ripeners",
 intro:"Pebbly soils drain superbly and bank daytime heat to radiate at night — ideal for ripening late-ripening varieties like Cabernet Sauvignon and Grenache.",
 tech:[
  {n:"Cabernet Sauvignon",d:"Deep gravel banks drain well and hold heat, ripening late Cabernet — the Left Bank's edge.",w:"Médoc & Graves (Left Bank Bordeaux)"},
  {n:"Grenache (GSM)",d:"Large rounded stones ('galets roulés') store the day's heat and radiate it overnight.",w:"Châteauneuf-du-Pape (S. Rhône)"},
  {n:"Bordeaux blends & Syrah",d:"Free-draining river gravels ripen Bordeaux varieties in a cool maritime climate.",w:"Gimblett Gravels, Hawke's Bay (NZ)"},
  {n:"Cabernet Sauvignon (terra rossa)",d:"'Terra rossa' — iron-rich red soil over limestone — gives elegant, structured Cabernet.",w:"Coonawarra (Australia)"}
 ],
 traps:[
  "Châteauneuf-du-Pape's famous 'galets roulés' are large rounded stones that store and radiate heat.",
  "Coonawarra's 'terra rossa' is red soil over limestone — its Cabernet signature."
 ]},

{name:"Clay & Marl",ic:"🟧",tag:"water-holding, cooler, Merlot",
 intro:"Dense, water-retentive, cooler soils that suit earlier-ripening, thirstier varieties — above all Merlot. Mixed with limestone, clay becomes 'marl'.",
 tech:[
  {n:"Merlot",d:"Cool, water-holding clay suits early-ripening Merlot — the Right Bank's signature.",w:"Pomerol & St-Émilion (Right Bank Bordeaux)"},
  {n:"Merlot (clay over iron)",d:"Pétrus famously sits on a clay plateau with iron-rich 'crasse de fer'.",w:"Pomerol"},
  {n:"Sangiovese",d:"Calcareous clay and marl ('galestro' & 'alberese') give structured Tuscan reds.",w:"Chianti, Montalcino (Tuscany)"},
  {n:"Tempranillo",d:"Clay-limestone holds water through hot summers for balanced reds.",w:"Rioja (Spain)"}
 ],
 traps:[
  "Right Bank (Pomerol, St-Émilion) = cooler, water-holding CLAY → MERLOT; Left Bank = warm GRAVEL → CABERNET.",
  "'Marl' = limestone + clay; Tuscany's 'galestro' and 'alberese' are its Sangiovese soils."
 ]},

{name:"Volcanic",ic:"🌋",tag:"minerality, distinctive wines",
 intro:"Basalt, tuff, ash and pumice — free-draining, often poor and mineral-rich, and frequently phylloxera-resistant. Home to some of the world's most distinctive wines.",
 tech:[
  {n:"Nerello Mascalese",d:"Black volcanic soils on Mount Etna give perfumed, mineral, high-altitude reds.",w:"Etna (Sicily)"},
  {n:"Assyrtiko",d:"Volcanic ash and pumice on a hot, windy island give intense, saline, high-acid whites.",w:"Santorini (Greece)"},
  {n:"Garganega",d:"Volcanic basalt gives Soave its mineral, almond character.",w:"Soave (Veneto)"},
  {n:"Furmint",d:"Volcanic soils underpin the great sweet and dry wines of Tokaj.",w:"Tokaj (Hungary)"},
  {n:"Pinot Noir",d:"Iron-rich red volcanic 'Jory' soils give structured, age-worthy Pinot.",w:"Dundee Hills, Willamette Valley (Oregon)"}
 ],
 traps:[
  "Santorini (Assyrtiko) and Sicily's Etna (Nerello Mascalese) are the classic volcanic-soil exam answers.",
  "Volcanic and sandy soils are often phylloxera-resistant, so vines there may be ungrafted."
 ]},

{name:"Sand & Alluvial",ic:"🏖️",tag:"low vigour, ungrafted vines",
 intro:"Free-draining, low-nutrient soils that give lighter, paler, aromatic wines — and, crucially, resist the phylloxera louse, so vines can grow ungrafted on their own roots.",
 tech:[
  {n:"Ramisco (ungrafted)",d:"Vines grow own-rooted in deep coastal sand that phylloxera cannot navigate.",w:"Colares (Portugal)"},
  {n:"Old-vine Grenache & Shiraz",d:"Sandy patches preserve ancient, ungrafted, pre-phylloxera vines.",w:"Barossa Valley (Australia)"},
  {n:"High-yield varieties (alluvial)",d:"Fertile river-deposited sand, silt and gravel boost vigour and yield — better for volume than top quality.",w:"Valley floors worldwide (e.g. parts of Mendoza, Central Valley)"}
 ],
 traps:[
  "Sandy soils resist phylloxera — which is why places like Colares keep ungrafted, own-rooted vines.",
  "Fertile alluvial valley floors favour quantity; the finest sites are usually poorer hillside soils."
 ]},

{name:"Beyond Soil",ic:"🧭",tag:"climate, aspect, water, altitude",
 intro:"Soil rarely acts alone. These factors often decide more than soil does — whether grapes ripen at all and whether they stay in balance.",
 terms:[
  {t:"Aspect (sun exposure)",d:"South-facing slopes (Northern Hemisphere) maximise sunlight and ripening — vital in cool regions like the Mosel and Côte d'Or."},
  {t:"Altitude",d:"Higher sites are cooler with bigger day-night swings that preserve acidity and colour — e.g. Mendoza's Uco Valley, Etna, Salta."},
  {t:"Diurnal range",d:"Warm days build sugar and flavour; cold nights lock in acidity and aromatics. Continental and high-altitude sites excel here."},
  {t:"Proximity to water",d:"Rivers, lakes and oceans moderate temperature, reflect light and bring cooling fog — e.g. Mosel, Finger Lakes, coastal California."},
  {t:"Rain shadow",d:"Mountains block rain and storms, giving dry, sunny vineyards — the Andes for Mendoza, the Cascades for Washington, the Vosges for Alsace."},
  {t:"Slope & drainage",d:"Slopes shed water and cold air (frost protection) and tilt the vines toward the sun."}
 ],
 traps:[
  "Northern Hemisphere: the best slopes face SOUTH (toward the sun). Southern Hemisphere: NORTH.",
  "Alsace is dry because the Vosges cast a rain shadow — the same principle as the Andes over Mendoza."
 ]}
];

/* ============ Dessert (Sweet) Wines reference ============
   Organized by HOW the sweetness is made — the exam framework. Same schema as
   WINE/SOIL (tech={n,d,w(where)}, terms={t,d}, traps[]). */
var INTRO_DESS=[
{name:"How Sweetness Is Made",ic:"🍯",tag:"the five routes to sweet",
 intro:"A wine is sweet because sugar REMAINS after fermentation — either by concentrating sugar in the grape so the yeast can't finish it, or by stopping fermentation while sugar is still there. The mark of a GREAT sweet wine is high acidity to balance all that sugar.",
 terms:[
  {t:"Noble rot (botrytis)",d:"Botrytis cinerea shrivels ripe grapes, concentrating sugar and adding honey, apricot and saffron. → Sauternes, Tokaji, TBA."},
  {t:"Drying (passito)",d:"Healthy grapes air-dried to raisins before fermenting, concentrating everything. → Recioto, Vin Santo."},
  {t:"Freezing (ice wine)",d:"Grapes frozen on the vine and pressed frozen; water stays as ice, sweet juice runs off. → Eiswein, Icewine."},
  {t:"Late harvest",d:"Grapes left to over-ripen and partly raisin on the vine. → Vendange Tardive, Spätlese/Auslese."},
  {t:"Fortification (mutage)",d:"Grape spirit added mid-fermentation halts the yeast, keeping natural sweetness. → Port, Muscat VDN, PX Sherry."}
 ],
 traps:[
  "The non-negotiable for great sweet wine is ACIDITY — without it sweetness is cloying. Riesling, Chenin, Furmint and Sémillon excel because they keep their acidity.",
  "Sweet ≠ low quality: some of the world's longest-lived, priciest wines are Yquem, Tokaji and Trockenbeerenauslese.",
  "Exams love asking WHICH method made a wine — concentrating sugar (rot/drying/freezing) is different from stopping fermentation (fortification)."
 ]},

{name:"Noble Rot (Botrytis)",ic:"🍄",tag:"Sauternes · Tokaji · TBA",
 intro:"In its benevolent 'noble rot' form, Botrytis cinerea punctures the skins and dehydrates the berry, concentrating sugar AND acid and adding honey, marmalade, ginger and saffron. It needs misty, humid mornings then dry, sunny afternoons; on healthy or unripe grapes the same fungus becomes destructive 'grey rot', a fault.",
 tech:[
  {n:"Sauternes & Barsac",d:"Sémillon-led, with Sauvignon Blanc and a little Muscadelle; rich and honeyed. Picked berry-by-berry over several passes. Château d'Yquem is the only Premier Cru Supérieur of 1855.",w:"Bordeaux (France)"},
  {n:"Tokaji Aszú",d:"Botrytised 'Aszú' berries (mainly Furmint) blended into a base wine; sweetness shown in puttonyos (historically 3–6) or residual sugar. Honeyed, racy, immortal.",w:"Tokaj (Hungary)"},
  {n:"Beerenauslese & Trockenbeerenauslese",d:"Top Prädikat levels — BA from botrytised berries, TBA from shrivelled botrytised berries; intensely sweet, high-acid, usually Riesling.",w:"Germany & Austria"},
  {n:"Sweet Chenin Blanc",d:"Botrytised Chenin: Quarts de Chaume, Bonnezeaux, Coteaux du Layon and moelleux Vouvray.",w:"Anjou & Touraine (Loire)"},
  {n:"Sélection de Grains Nobles (SGN)",d:"Alsace's botrytis selection (Riesling, Pinot Gris, Gewürztraminer, Muscat) — the sweeter step ABOVE Vendange Tardive.",w:"Alsace (France)"},
  {n:"Eszencia",d:"The pinnacle of Tokaj: the free-run nectar of Aszú berries, so sugary it barely ferments — very low alcohol, syrupy, near-eternal.",w:"Tokaj (Hungary)"}
 ],
 traps:[
  "Noble rot (Botrytis cinerea) is GOOD; 'grey rot' on healthy/unripe grapes is a fault — same fungus, different conditions.",
  "Sauternes is SÉMILLON-dominant (not Sauvignon Blanc). Château d'Yquem is the lone Premier Cru Supérieur.",
  "Tokaji sweetness was counted in 'puttonyos'; since 2013 most Aszú is labelled by residual sugar (≈5–6 putt). Eszencia is the rare, barely-alcoholic nectar.",
  "Botrytis adds a distinctive saffron/marmalade note — not every late-harvest sweet wine is botrytised."
 ]},

{name:"Dried-Grape (Passito)",ic:"🍇",tag:"raisined on mats & straw",
 intro:"Healthy grapes are harvested then air-dried — on mats, racks or straw — for weeks to months until they raisin ('appassimento'). This concentrates sugar, acid and flavour before a slow fermentation. No botrytis needed.",
 tech:[
  {n:"Recioto della Valpolicella",d:"Sweet RED from dried Corvina — the sweet sibling of (dry) Amarone, made by stopping fermentation early.",w:"Veneto (Italy)"},
  {n:"Recioto di Soave",d:"Sweet WHITE from dried Garganega — Soave's dessert version.",w:"Veneto (Italy)"},
  {n:"Vin Santo",d:"'Holy wine' from dried Trebbiano/Malvasia, fermented and aged for years in small sealed 'caratelli' in warm lofts — oxidative and nutty; classic with cantucci.",w:"Tuscany (Italy)"},
  {n:"Passito di Pantelleria",d:"Lush sweet wine from sun-dried Zibibbo (Muscat of Alexandria) on a windy volcanic island.",w:"Sicily (Italy)"},
  {n:"Vin de Paille (straw wine)",d:"Grapes dried on straw mats; intensely sweet and rare.",w:"Jura & N. Rhône (France)"},
  {n:"Commandaria",d:"Ancient sweet wine from sun-dried Xynisteri & Mavro — one of the world's oldest named wines.",w:"Cyprus"}
 ],
 traps:[
  "Recioto = SWEET (fermentation stopped early); Amarone = DRY (fermented out). Both start from the same dried Valpolicella grapes.",
  "Vin Santo means 'holy wine' — dried-grape AND oxidatively aged in caratelli.",
  "Passito wines use HEALTHY grapes dried after picking — no botrytis (unlike Sauternes/Tokaji)."
 ]},

{name:"Ice Wine (Eiswein)",ic:"❄️",tag:"frozen on the vine",
 intro:"Grapes are left on the vine into winter and harvested and pressed while naturally FROZEN. The water stays behind as ice crystals, so only a tiny amount of intensely sweet, high-acid juice runs off — making ice wine rare, gruelling to make and expensive.",
 tech:[
  {n:"Eiswein",d:"Riesling (and others) frozen on the vine; a German/Austrian Prädikat-level wine requiring a hard natural frost (around −7°C).",w:"Germany & Austria"},
  {n:"Icewine (VQA)",d:"Canada is the world's LARGEST producer — mainly Vidal and Riesling (also Cabernet Franc); strict VQA rules, naturally frozen.",w:"Canada (Niagara, Okanagan)"}
 ],
 terms:[
  {t:"Why it's so rare",d:"A hard frost must arrive while the grapes are still healthy on the vine; yields are tiny and picking happens at night in freezing cold."},
  {t:"Cryoextraction",d:"Artificially freezing PICKED grapes in a freezer — a shortcut that is NOT permitted for true Eiswein/Icewine."}
 ],
 traps:[
  "Ice wine grapes freeze NATURALLY on the vine. Freezing picked grapes is 'cryoextraction' and disqualifies a wine from being Eiswein/Icewine.",
  "Canada — not Germany — is the largest icewine producer, thanks to reliably cold winters.",
  "Ice wine concentrates by FREEZING, not by botrytis (grapes stay healthy) or drying."
 ]},

{name:"Late Harvest",ic:"☀️",tag:"over-ripened on the vine",
 intro:"The simplest route: leave grapes on the vine past normal ripeness so they over-ripen and partly shrivel, building sugar. Some late-harvest wines also catch botrytis; many don't. Sweetness runs from off-dry to lusciously sweet.",
 tech:[
  {n:"Vendange Tardive (VT)",d:"Alsace 'late harvest' from Riesling, Pinot Gris, Gewürztraminer or Muscat — concentrated, off-dry to sweet. SGN (botrytis) is the sweeter step above it.",w:"Alsace (France)"},
  {n:"Spätlese & Auslese",d:"German/Austrian Prädikat levels by ripeness; can be made dry OR sweet. Auslese ('select harvest') is riper than Spätlese.",w:"Germany & Austria"},
  {n:"Vin de Constance",d:"Legendary sweet Muscat from late-harvested, raisined grapes — historic, and notably NOT botrytised or fortified.",w:"Constantia (South Africa)"},
  {n:"New World 'Late Harvest'",d:"Riesling, Gewürztraminer, Viognier and others picked late; style varies and the term is largely unregulated.",w:"USA, Australia, etc."}
 ],
 traps:[
  "In Alsace, Vendange Tardive (late harvest) sits BELOW Sélection de Grains Nobles (botrytis).",
  "German Prädikat (Kabinett→TBA) is a RIPENESS ladder, not a sweetness guarantee — a Spätlese can be bone-dry (Trocken).",
  "Vin de Constance is late-harvest/raisined Muscat — famously neither botrytised nor fortified."
 ]},

{name:"Fortified Sweet Wines",ic:"🥃",tag:"spirit locks in the sugar",
 intro:"Add neutral grape spirit DURING fermentation ('mutage') and the yeast dies before eating all the sugar — leaving a sweet, higher-alcohol wine. Regions differ in when the spirit goes in and how the wine is then aged.",
 tech:[
  {n:"Port (sweet styles)",d:"Fortified mid-fermentation. Ruby family (fresh): Ruby, Reserve, LBV, Vintage (bottle-aged, declared years). Tawny family (oxidative): 10/20/30/40-Year and single-vintage Colheita.",w:"Douro (Portugal)"},
  {n:"Madeira (sweet styles)",d:"Heated (estufagem/canteiro) and graded by grape: Bual (rich) and Malmsey/Malvasia (sweetest); Sercial and Verdelho are drier. Nearly immortal once open.",w:"Madeira (Portugal)"},
  {n:"Pedro Ximénez (PX)",d:"Sherry from sun-dried PX grapes — the darkest, sweetest, most viscous Sherry (raisin, fig, molasses). Moscatel is the other naturally sweet Sherry; Cream/Pale Cream are sweetened blends.",w:"Jerez (Spain)"},
  {n:"Vins Doux Naturels (VDN)",d:"Fortified to retain sweetness: Muscat de Beaumes-de-Venise and Rivesaltes (Muscat); Banyuls and Maury (Grenache — can age oxidatively, 'rancio').",w:"S. France"},
  {n:"Marsala",d:"Sicilian fortified wine; sweetness secco→semisecco→dolce, aged Fine→Superiore→Vergine.",w:"Sicily (Italy)"},
  {n:"Rutherglen Muscat",d:"Australia's lusciously sweet, barrel-aged fortified Muscat ('sticky'), tiered Rutherglen → Classic → Grand → Rare.",w:"Victoria (Australia)"}
 ],
 traps:[
  "Fortified sweet wines stop fermentation with SPIRIT (mutage) — the sugar is the grape's own, not added.",
  "Madeira sweetness by grape: Sercial (dry) → Verdelho → Bual → Malmsey (sweetest).",
  "Pedro Ximénez (PX) is the sweetest, darkest Sherry; most Sherry ferments DRY and sweet styles are blended or raisined.",
  "Colheita (single-vintage TAWNY, wood-aged) ≠ Vintage Port (single-vintage RUBY, bottle-aged)."
 ]},

{name:"Serving & Pairing",ic:"🍽️",tag:"temperature, pours, partners",
 intro:"Sweet wines are served chilled in small pours, and the golden rule is to make sure the WINE is at least as sweet as the dessert — or to play sweetness against salty, savoury food for contrast.",
 terms:[
  {t:"Serve chilled, small pours",d:"Most dessert wines show best lightly chilled; their richness means a 2–3 oz pour is plenty."},
  {t:"Wine ≥ dessert in sweetness",d:"If the dish is sweeter than the wine, the wine tastes thin and sour — match or exceed the dessert's sweetness."},
  {t:"Sweet + salty / savoury",d:"Classic contrast pairings: Sauternes with foie gras or Roquefort; Port with Stilton; PX poured over vanilla ice cream."},
  {t:"Opened-bottle life",d:"Fortified and oxidative wines (Madeira, Tawny, PX) last weeks to months open; fresh botrytis wines fade faster, though chilled Sauternes keeps a few days."}
 ],
 traps:[
  "Golden rule: the wine should be AS SWEET AS or sweeter than the dessert, or it tastes sour and watery.",
  "Salty blue cheese (Roquefort/Stilton) is a classic FOIL for sweet wine — sweet + salty, not sweet + sweet.",
  "Oxidative fortifieds (Madeira, Tawny, Oloroso, PX) survive weeks open; delicate botrytis wines are more fragile."
 ]},

{name:"Must-Know Names & Tells",ic:"⭐",tag:"the marquee bottles",
 intro:"The flagship sweet wines you're expected to recognise — and the distinctions examiners love to test (method, grape and region).",
 tech:[
  {n:"Château d'Yquem",d:"The legendary Sauternes; the sole 'Premier Cru Supérieur' of the 1855 classification. Botrytised Sémillon.",w:"Sauternes (France)"},
  {n:"Tokaji Aszú & Eszencia",d:"Hungary's botrytised Furmint; Eszencia is the rare free-run nectar.",w:"Tokaj (Hungary)"},
  {n:"Trockenbeerenauslese (TBA)",d:"The sweetest German/Austrian Prädikat, from shrivelled botrytised berries (Riesling).",w:"Germany & Austria"},
  {n:"Vin de Constance",d:"Historic late-harvest Muscat once prized by European royalty.",w:"Constantia (South Africa)"},
  {n:"Pedro Ximénez",d:"The sweetest, darkest Sherry, from sun-dried grapes.",w:"Jerez (Spain)"},
  {n:"Rutherglen Muscat",d:"Australia's barrel-aged fortified 'sticky'.",w:"Victoria (Australia)"}
 ],
 traps:[
  "Match the METHOD: Sauternes/Tokaji/TBA = botrytis; Recioto/Vin Santo = dried grapes; Eiswein = frozen; Port/PX/VDN = fortified.",
  "Match the GRAPE: Sauternes = Sémillon; Tokaji = Furmint; Eiswein/Icewine = Riesling/Vidal; PX = Pedro Ximénez; Constance = Muscat.",
  "Know the sweetness words: Sec (dry) · Demi-Sec (off-dry) · Moelleux (sweet) · Doux / Liquoreux (lusciously sweet)."
 ]}
];


